import java.util.*;

public class Main {
    String removeOuterParentheses(String s) {
        List<String> primitives = new ArrayList<>();                                // split s into its primitive (balanced, non-empty) pieces first
        int depth = 0, start = 0;
        for (int i = 0; i < s.length(); i++) {
            depth += (s.charAt(i) == '(') ? 1 : -1;
            if (depth == 0) {                                                          // a primitive piece ends exactly when depth returns to 0
                primitives.add(s.substring(start, i + 1));
                start = i + 1;
            }
        }
        StringBuilder result = new StringBuilder();
        for (String p : primitives) result.append(p.substring(1, p.length() - 1));       // strip each primitive's own outermost pair of parentheses
        return result.toString();
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.removeOuterParentheses("(()())(())"));
    }
}

