#include <bits/stdc++.h>
using namespace std;

string removeOuterParentheses(string s) {
    vector<string> primitives;                                                       // split s into its primitive (balanced, non-empty) pieces first
    int depth = 0, start = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        depth += (s[i] == '(') ? 1 : -1;
        if (depth == 0) {                                                                // a primitive piece ends exactly when depth returns to 0
            primitives.push_back(s.substr(start, i - start + 1));
            start = i + 1;
        }
    }
    string result;
    for (auto& p : primitives) result += p.substr(1, p.size() - 2);                          // strip each primitive's own outermost pair of parentheses
    return result;
}

int main() {
    cout << removeOuterParentheses("(()())(())") << endl;
    return 0;
}

