def remove_outer_parentheses(s):
    result = []
    depth = 0
    for c in s:
        if c == '(':
            if depth > 0:
                result.append(c)                                            # an INNER open paren: keep it
            depth += 1                                                     # entering one level deeper
        else:
            depth -= 1                                                    # leaving one level (do this BEFORE checking, for closes)
            if depth > 0:
                result.append(c)                                           # an INNER close paren: keep it
    return ''.join(result)


