        int depth = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                if (depth > 0) result.append(c);                                          // an INNER open paren: keep it
                depth++;                                                                     // entering one level deeper
            } else {
                depth--;                                                                     // leaving one level (do this BEFORE checking, for closes)
                if (depth > 0) result.append(c);                                              // an INNER close paren: keep it
            }
        }
        return result.toString();
    }

